CREATE TYPE "Role" AS ENUM ('MEMBER','EDITOR','MODERATOR','ADMIN');
CREATE TYPE "PublicationStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE "DiscussionKind" AS ENUM ('DISCUSSION','QUESTION');
CREATE TYPE "ReportStatus" AS ENUM ('OPEN','REVIEWED','DISMISSED','ACTIONED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"displayName" TEXT NOT NULL,"bio" TEXT,"role" "Role" NOT NULL DEFAULT 'MEMBER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Topic" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL UNIQUE,"description" TEXT NOT NULL,"parentId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Topic_parentId_fkey" FOREIGN KEY("parentId") REFERENCES "Topic"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "Article" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"summary" TEXT NOT NULL,"content" TEXT NOT NULL,"status" "PublicationStatus" NOT NULL DEFAULT 'DRAFT',"authorId" TEXT NOT NULL,"publishedAt" TIMESTAMP(3),"updatedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Article_authorId_fkey" FOREIGN KEY("authorId") REFERENCES "User"("id"));
CREATE TABLE "ArticleTopic" ("articleId" TEXT NOT NULL,"topicId" TEXT NOT NULL, PRIMARY KEY("articleId","topicId"), FOREIGN KEY("articleId") REFERENCES "Article"("id") ON DELETE CASCADE, FOREIGN KEY("topicId") REFERENCES "Topic"("id") ON DELETE CASCADE);
CREATE TABLE "ArticleSource" ("id" TEXT PRIMARY KEY,"articleId" TEXT NOT NULL,"title" TEXT NOT NULL,"url" TEXT NOT NULL,"license" TEXT,"accessedAt" TIMESTAMP(3), FOREIGN KEY("articleId") REFERENCES "Article"("id") ON DELETE CASCADE);
CREATE TABLE "ArticleRevision" ("id" TEXT PRIMARY KEY,"articleId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"title" TEXT NOT NULL,"content" TEXT NOT NULL,"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY("articleId") REFERENCES "Article"("id") ON DELETE CASCADE, FOREIGN KEY("authorId") REFERENCES "User"("id"));
CREATE TABLE "Discussion" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"kind" "DiscussionKind" NOT NULL DEFAULT 'DISCUSSION',"status" "PublicationStatus" NOT NULL DEFAULT 'PUBLISHED',"authorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, FOREIGN KEY("authorId") REFERENCES "User"("id"));
CREATE TABLE "DiscussionTopic" ("discussionId" TEXT NOT NULL,"topicId" TEXT NOT NULL, PRIMARY KEY("discussionId","topicId"), FOREIGN KEY("discussionId") REFERENCES "Discussion"("id") ON DELETE CASCADE, FOREIGN KEY("topicId") REFERENCES "Topic"("id") ON DELETE CASCADE);
CREATE TABLE "Comment" ("id" TEXT PRIMARY KEY,"body" TEXT NOT NULL,"authorId" TEXT NOT NULL,"discussionId" TEXT,"parentId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY("authorId") REFERENCES "User"("id"), FOREIGN KEY("discussionId") REFERENCES "Discussion"("id") ON DELETE CASCADE, FOREIGN KEY("parentId") REFERENCES "Comment"("id"));
CREATE TABLE "ModerationReport" ("id" TEXT PRIMARY KEY,"reason" TEXT NOT NULL,"status" "ReportStatus" NOT NULL DEFAULT 'OPEN',"reporterId" TEXT NOT NULL,"articleId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY("reporterId") REFERENCES "User"("id"), FOREIGN KEY("articleId") REFERENCES "Article"("id"));
CREATE INDEX "Article_status_publishedAt_idx" ON "Article"("status","publishedAt"); CREATE INDEX "Topic_parentId_idx" ON "Topic"("parentId"); CREATE INDEX "Discussion_kind_status_createdAt_idx" ON "Discussion"("kind","status","createdAt"); CREATE INDEX "ModerationReport_status_createdAt_idx" ON "ModerationReport"("status","createdAt");
